package app.stride.seven;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.widget.*;import android.graphics.Color;import org.json.*;import java.util.*;

public class TrackingActivity extends Activity {
    SharedPreferences p;TextView stats,history;EditText target;Spinner type;String pending="";int spacing;final Handler timer=new Handler();
    Button start,pause,finish,enable,disable;
    @Override public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences(TrackingService.PREF,0);spacing=(int)(getResources().getDisplayMetrics().density*18);
        ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(spacing,spacing,spacing,spacing*2);box.setBackgroundColor(Color.rgb(245,245,247));scroll.addView(box);setContentView(scroll);
        TextView title=new TextView(this);title.setText("Live activity");title.setTextSize(31);title.setTextColor(Color.rgb(29,29,31));title.setTypeface(null,1);box.addView(title);
        TextView info=new TextView(this);info.setText("Your profile and records stay on this phone. Carry your phone for steps. Enable counting each time tracking is stopped or your phone restarts. GPS runs only during a session.\n\nStep totals start when counting is enabled; they exclude earlier steps and may differ from Samsung Health. These totals are never added to Samsung Health totals.\n");info.setTextColor(Color.rgb(85,85,93));info.setTextSize(14);box.addView(info);
        stats=new TextView(this);stats.setTextSize(20);stats.setTextColor(Color.rgb(29,29,31));box.addView(stats);
        enable=button(box,"Enable all-day step counting",()->permissions("steps-on"));disable=button(box,"Stop step counting",()->send("steps-off"));
        TextView label=new TextView(this);label.setText("Run / walk distance target (km)");box.addView(label);target=new EditText(this);target.setInputType(8194);target.setText(p.getString("targetKm","7"));box.addView(target);
        type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Run","Walk"}));box.addView(type);
        start=button(box,"Start activity",()->permissions("start"));pause=button(box,"Pause / Resume",()->{if(p.getBoolean("paused",false)||!TrackingService.alive)permissions("resume");else send("pause");});finish=button(box,"Finish & save",()->send("finish"));
        button(box,"Test goal notification",()->{pending="test";if(checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},71);else testAlert();});
        TextView note=new TextView(this);note.setText("\nA notification appears once per daily step goal and once per activity distance goal. Allow notifications and Physical activity; choose Precise location while using the app for GPS. Keep Stride out of Samsung's sleeping apps if tracking stops with the screen locked. Battery restrictions, force-stop and reboot can interrupt tracking. Indoor GPS is unreliable.\n\nCompleted sessions appear in Stride’s combined Activity history under Progress. The planner backup now includes these sessions. An optional raw export is also available below.\n");box.addView(note);
        button(box,"Export raw live history",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"stride-live-history.json");startActivityForResult(i,72);});
        history=new TextView(this);box.addView(history);button(box,"Back to planner",()->finish());
    }
    Button button(LinearLayout box,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(15);b.setMinHeight((int)(getResources().getDisplayMetrics().density*48));
        boolean primary=title.startsWith("Start activity")||title.startsWith("Enable all-day");android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setColor(primary?Color.rgb(0,122,255):Color.WHITE);background.setCornerRadius((int)(getResources().getDisplayMetrics().density*13));if(!primary)background.setStroke((int)getResources().getDisplayMetrics().density,Color.rgb(222,222,227));b.setBackground(background);b.setTextColor(primary?Color.WHITE:Color.rgb(0,93,190));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=spacing/2;box.addView(b,lp);return b;}
    void permissions(String action){pending=action;ArrayList<String> needs=new ArrayList<>();needs.add("android.permission.POST_NOTIFICATIONS");if(action.equals("steps-on"))needs.add("android.permission.ACTIVITY_RECOGNITION");else{needs.add("android.permission.ACCESS_FINE_LOCATION");needs.add("android.permission.ACCESS_COARSE_LOCATION");}boolean missing=false;for(String s:needs)if(checkSelfPermission(s)!=PackageManager.PERMISSION_GRANTED)missing=true;if(missing)requestPermissions(needs.toArray(new String[0]),71);else send(action);}
    @Override public void onRequestPermissionsResult(int c,String[] names,int[] results){super.onRequestPermissionsResult(c,names,results);if(c!=71)return;if(pending.equals("test")){testAlert();return;}String required=pending.equals("steps-on")?"android.permission.ACTIVITY_RECOGNITION":"android.permission.ACCESS_FINE_LOCATION";if(checkSelfPermission(required)!=PackageManager.PERMISSION_GRANTED){Toast.makeText(this,"Tracking needs "+(pending.equals("steps-on")?"Physical activity":"Precise location")+" permission.",1).show();return;}if(checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)Toast.makeText(this,"Notifications are denied. Goal alerts will not be shown.",1).show();send(pending);}
    void send(String action){Intent i=new Intent(this,TrackingService.class).setAction(action);if(action.equals("start")){try{double km=Double.parseDouble(target.getText().toString());if(!Double.isFinite(km)||km<0.1||km>100)throw new Exception();i.putExtra("goal",km*1000).putExtra("kind",type.getSelectedItem().toString());p.edit().putString("targetKm",String.valueOf(km)).apply();}catch(Exception e){target.setError("Enter 0.1 to 100 km");return;}}
        p.edit().remove("error").apply();try{if(TrackingService.alive)startService(i);else if(action.equals("steps-on")||action.equals("start")||action.equals("resume"))startForegroundService(i);else startService(i);}catch(Exception e){Toast.makeText(this,"Could not start tracking. Check permissions and reopen this screen.",1).show();}}
    void testAlert(){NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("goals","Goal completed",NotificationManager.IMPORTANCE_HIGH));if(!nm.areNotificationsEnabled()){Toast.makeText(this,"Enable Stride notifications in Android Settings.",1).show();return;}nm.notify(202,new Notification.Builder(this,"goals").setSmallIcon(android.R.drawable.ic_menu_compass).setContentTitle("Stride goal alerts are ready").setContentText("This is a test notification, not a completed goal.").setAutoCancel(true).build());}
    final Runnable refresh=new Runnable(){public void run(){render();timer.postDelayed(this,1000);}};
    @Override public void onResume(){super.onResume();timer.post(refresh);}@Override public void onPause(){timer.removeCallbacks(refresh);super.onPause();}
    void render(){boolean active=p.getBoolean("active",false),running=TrackingService.alive;double km=p.getFloat("meters",0)/1000.0;long seconds=p.getLong("elapsed",0)/1000;String pace=km>0.02?String.format(Locale.US,"%.1f min/km",seconds/60.0/km):"—";
        stats.setText(p.getString("name","Your profile")+"\n"+p.getInt("steps."+TrackingService.today(),0)+" / "+p.getInt("stepGoal",10000)+" steps today\n"+(running&&p.getBoolean("counting",false)?"Step counting on":"Step counting off")+"\n\n"+(active?String.format(Locale.US,"%s · %.2f / %.2f km\n%d:%02d · %s\n%s\n%s",p.getString("kind","Run"),km,p.getFloat("goal",7000)/1000.0,seconds/60,seconds%60,pace,(!running||p.getBoolean("paused",false))?"Paused — tap Resume":"Tracking",p.getString("gps","Waiting for GPS")):"Ready for a run or walk")+"\n"+p.getString("error",""));
        start.setEnabled(!active);pause.setEnabled(active);pause.setText(!running||p.getBoolean("paused",false)?"Resume":"Pause");finish.setEnabled(active);target.setEnabled(!active);type.setEnabled(!active);enable.setEnabled(!running||!p.getBoolean("counting",false));disable.setEnabled(running&&p.getBoolean("counting",false));
        try{JSONArray a=new JSONArray(p.getString("history","[]"));StringBuilder text=new StringBuilder("\nCompleted sessions\n");for(int n=a.length()-1;n>=Math.max(0,a.length()-30);n--){JSONObject s=a.getJSONObject(n);text.append(String.format(Locale.US,"\n%s · %s · %.2f km · %.1f min\n",s.getString("date"),s.getString("type"),s.getDouble("meters")/1000,s.getLong("elapsedMs")/60000.0));}history.setText(text.toString());}catch(Exception e){history.setText("History could not be displayed.");}}
    @Override protected void onActivityResult(int c,int result,Intent i){super.onActivityResult(c,result,i);if(c==72&&result==RESULT_OK&&i!=null&&i.getData()!=null){try(java.io.OutputStream out=getContentResolver().openOutputStream(i.getData())){JSONObject data=new JSONObject();data.put("format","stride-live-v1").put("profile",p.getString("name","")).put("sessions",new JSONArray(p.getString("history","[]")));JSONObject days=new JSONObject();for(Map.Entry<String,?> e:p.getAll().entrySet())if(e.getKey().startsWith("steps."))days.put(e.getKey().substring(6),e.getValue());data.put("steps",days);out.write(data.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"Live history exported",0).show();}catch(Exception e){Toast.makeText(this,"Export failed. Try again.",1).show();}}}
}
